/* Original LedgerPeer FIA and ACCA revision lesson library. Based on official ACCA 2026–27 syllabus topic codes. */
(function(root){'use strict';root.LedgerFiaNotes={"FA2:A1":{"paper":"FA2","code":"A1","summary":"Accounting information is useful when it faithfully represents transactions and helps users make decisions. Apply accrual accounting, going concern, consistency and materiality to the situation instead of memorising isolated definitions.","steps":["An asset is a present economic resource controlled because of past events. A liability is a present obligation to transfer an economic resource arising from past events.","Revenue and expenses reflect performance; cash receipts and payments are not necessarily revenue or expense of the period.","Relevant information can influence decisions; faithful representation is complete, neutral and free from material error."],"formula":"Assets = Equity + Liabilities.","example":"A customer pays $2,400 in December for January services. December entry: debit bank $2,400, credit deferred income $2,400. Recognise the revenue as services are delivered in January.","trap":"Do not confuse cash received with revenue earned.","check":"Is an advance customer payment an asset, revenue or liability?","answer":"Initially a liability (deferred income): the business still owes goods or services."},"FA2:B1":{"paper":"FA2","code":"B1","summary":"Recognise the building blocks of the financial statements before selecting debits and credits.","steps":["Assets are resources controlled; liabilities are present obligations; equity is the residual interest.","Revenue increases equity other than owner contributions. Expenses reduce equity other than distributions.","Use the financial position equation to identify missing amounts and distinguish capital from profit."],"formula":"Net assets = Assets − Liabilities = Equity.","example":"If total assets are $80,000 and liabilities $31,000, closing equity is $49,000. This is not automatically profit, because equity also changes with capital introduced and drawings.","trap":"A rent prepayment is an asset; unpaid rent is a liability.","check":"If equity rises $20,000 after new capital of $8,000 and drawings of $3,000, what is profit?","answer":"Profit = 20,000 − 8,000 + 3,000 = $15,000."},"FA2:C1":{"paper":"FA2","code":"C1","summary":"Journals record debits and credits and explain the business event behind every adjustment. Every complete journal must balance.","steps":["A debit increases assets and expenses but decreases liabilities, equity and income.","A credit increases liabilities, equity and income but decreases assets and expenses.","Narrate corrections, accruals, prepayments and depreciation; then post them to the ledger."],"formula":"Total debits = Total credits.","example":"Accrue $350 electricity used but unpaid: Dr electricity expense $350 / Cr accrued expense payable $350. Settle later: Dr accrued expense payable / Cr bank.","trap":"Never use a suspense account merely because the narrative looks difficult; first identify both affected accounts.","check":"How do you record an owner injecting $5,000 into the bank?","answer":"Dr bank $5,000 / Cr capital $5,000."},"FA2:C2":{"paper":"FA2","code":"C2","summary":"The general ledger groups postings by account; each transaction affects at least two accounts. Balancing shows the net debit or credit carried forward.","steps":["Record the debit or credit on its appropriate side and include the opposing account as the double-entry reference.","For asset accounts, an opening balance and increases generally appear on the debit side; for liability accounts they usually appear on the credit side.","Calculate the missing balance carried down as the amount that equalises the two sides, then bring it down on the opposite side next period."],"formula":"Closing ledger balance = Opening balance + increases − decreases (using the account's normal balance convention).","example":"Trade receivables: opening Dr $4,000; credit sales Dr $7,000; cash receipts Cr $6,200; closing balance Dr $4,800.","trap":"The balance carried down is a balancing figure, not an additional transaction.","check":"If a payable starts at $2,000, purchases on credit are $5,000 and payments are $4,100, closing payable?","answer":"$2,900 credit (2,000 + 5,000 − 4,100)."},"FA2:D1":{"paper":"FA2","code":"D1","summary":"Sales and purchases affect revenue, cost of sales, inventory and receivable/payable balances. Determine whether amounts are inclusive of sales tax and whether returns are inwards or outwards.","steps":["Sales returns (returns inwards) reduce revenue and trade receivables.","Purchase returns (returns outwards) reduce purchase cost and trade payables.","With a tax-inclusive figure, divide by 1 + tax rate to recover the net sales/purchase amount."],"formula":"Net amount = Tax-inclusive amount ÷ (1 + tax rate).","example":"An invoice totals $1,080 including 8% tax. Net purchase $1,000; input tax $80. The payable is $1,080.","trap":"Gross profit is reduced by sales returns, not by purchase returns treated as a sales expense.","check":"If credit sales of $540 include 8% tax, how much is revenue before tax?","answer":"$500 revenue; $40 output tax."},"FA2:D2":{"paper":"FA2","code":"D2","summary":"Cash and bank transactions are recorded in the cash book and checked against bank statements. Distinguish a payment or receipt from an adjustment in the bank reconciliation.","steps":["Debit the bank ledger for receipts; credit it for payments.","A dishonoured cheque, bank charge, standing order or direct credit not yet in the cash book is entered in the cash book first.","Unpresented cheques and outstanding lodgements are timing items for reconciliation, not duplicate ledger entries."],"formula":"Adjusted cash-book balance = Existing balance ± unrecorded bank transactions.","example":"The bank statement shows a $40 fee absent from the cash book: Dr bank charges $40 / Cr bank $40. Then reconcile timing differences.","trap":"Bank overdraft is a liability, not a negative cash asset on the statement of financial position.","check":"A direct credit of $700 appears on the bank statement but not in the cash book. Which side changes?","answer":"Dr bank $700; Cr the account corresponding to the payer or income."},"FA2:D3":{"paper":"FA2","code":"D3","summary":"Inventory is normally measured at the lower of cost and net realisable value (NRV). Cost flows through cost of sales when goods are sold.","steps":["Cost includes purchase price and other directly attributable costs of bringing inventory to its present location and condition.","NRV is estimated selling price less costs to complete and sell.","Under periodic weighted average, recompute average unit cost from total available units and costs; do not replace it with the latest purchase price."],"formula":"Cost of sales = Opening inventory + Purchases − Closing inventory.","example":"100 units cost $400 and 200 units cost $1,000; weighted average = $1,400/300 = $4.6667/unit. An issue of 90 units costs $420 under periodic weighted average.","trap":"LIFO is not permitted under IAS 2; do not assume it is acceptable just because it appears in management costing questions.","check":"An inventory item costs $70 and its NRV is $64. Carry it at what amount?","answer":"$64, the lower of cost and NRV."},"FA2:D4":{"paper":"FA2","code":"D4","summary":"Tangible non-current assets are capitalised when they provide future economic benefits and their cost can be measured reliably. Depreciation allocates depreciable cost over useful life.","steps":["Initial cost includes directly attributable installation, transport and costs needed to make the asset ready for use.","Straight-line depreciation spreads (cost − residual value) equally over useful life; reducing balance applies a fixed percentage to opening carrying amount.","On disposal, remove original cost and accumulated depreciation; compare proceeds with carrying amount to determine gain or loss."],"formula":"Straight line/year = (Cost − Residual value) ÷ Useful life.","example":"Machine costs $23,000, residual $3,000, life five years. Annual depreciation = $4,000. After two full years, carrying amount $15,000.","trap":"Do not expense routine repairs as a new asset or treat sale proceeds as disposal profit.","check":"If a machine carrying amount is $7,000 and sale proceeds are $8,500, what is the gain?","answer":"$1,500 gain on disposal."},"FA2:D5":{"paper":"FA2","code":"D5","summary":"Accruals, prepayments, accrued income and deferred income make the statements reflect the period that earns or consumes the benefit.","steps":["Accrued expense: recognised as an expense now, paid later; liability.","Prepayment: paid now, consumed later; asset.","Accrued income: earned now, collected later; asset. Deferred income: collected now, earned later; liability."],"formula":"Expense for period = Cash paid + Closing accrual − Opening accrual − Closing prepayment + Opening prepayment.","example":"Pay $1,200 annual insurance on 1 October for a 31 December year-end. Three months expense $300; nine months prepayment $900.","trap":"Accrued income is not the same as deferred income; one is receivable, the other is still owed in services.","check":"At year-end, $450 electricity remains unpaid. What is the entry?","answer":"Dr electricity expense $450 / Cr accrued expenses $450."},"FA2:D6":{"paper":"FA2","code":"D6","summary":"Receivables and payables must reflect amounts expected to be collected or settled. Irrecoverable debts are written off; allowances estimate further expected losses.","steps":["Write off a confirmed irrecoverable debt: Dr irrecoverable debt expense / Cr trade receivables.","An increased allowance: Dr irrecoverable debt expense / Cr allowance for receivables. A decrease reverses that expense.","Present trade receivables net of the allowance, while keeping the gross balance visible in working accounts.","Provisions are liabilities of uncertain timing or amount; recognise where there is a present obligation, probable outflow and reliable estimate."],"formula":"Net receivables = Gross receivables − Closing allowance.","example":"Gross receivables $20,000; write off $1,000; new allowance 5% of remaining $19,000 = $950. Net receivables $18,050. If old allowance was $600, increase expense by $350.","trap":"A specific write-off is not automatically an increase in the general allowance; calculate the remaining base first.","check":"The allowance falls from $700 to $500. Is the change an expense?","answer":"No: recognise a $200 credit (decrease in irrecoverable debt expense)."},"FA2:D7":{"paper":"FA2","code":"D7","summary":"Capital, drawings and finance costs need separate classifications so owner transactions do not distort operating profit.","steps":["Capital introduced increases equity, not income. Drawings reduce equity, not expenses.","Interest on a loan is finance cost; repayment of principal reduces the liability.","Split debt into current and non-current parts according to when contractual repayments fall due."],"formula":"Closing capital = Opening capital + Additional capital + Profit − Drawings.","example":"Loan $30,000 with $6,000 principal repayable in the next 12 months: classify $6,000 current and $24,000 non-current, ignoring any other contractual terms.","trap":"Do not record the whole loan repayment as an expense: only the interest element is a finance cost.","check":"Owner withdraws $800 cash for personal use. Effect?","answer":"Dr drawings $800 / Cr cash $800; no operating expense."},"FA2:E1":{"paper":"FA2","code":"E1","summary":"Bank reconciliation explains the difference between the corrected cash-book balance and the balance reported by the bank on the same date.","steps":["Update the cash book for bank charges, interest, standing orders, direct debits and errors not yet recorded.","Start from the corrected cash-book balance and adjust only timing items such as unpresented cheques and deposits not yet credited.","Use a consistent sign convention when balancing a bank overdraft."],"formula":"Corrected cash book ± Timing differences = Bank statement balance.","example":"Corrected bank ledger $4,200 debit; deposits not yet credited $800; unpresented cheques $500. Bank statement = 4,200 − 800 + 500 = $3,900.","trap":"A bank fee not recorded in the books is not an outstanding cheque; post it before reconciling.","check":"The bank statement is $1,000 higher than cash book because of a payment not yet presented. What is the payment's effect?","answer":"The cash book already records payment, but the bank statement has not yet reduced; bank statement is higher."},"FA2:E2":{"paper":"FA2","code":"E2","summary":"Supplier statement reconciliations compare the payable ledger with the supplier's record, identifying omissions, errors and timing differences.","steps":["Check invoices and credit notes not yet entered on either side.","Identify cash paid or discounts recorded by one side but not the other.","Reconcile invoice references and dates before making corrections; some items are only timing differences."],"formula":"Supplier ledger balance ± Reconciling items = Supplier statement balance.","example":"Our ledger $2,800 payable; supplier statement $3,200 because a $400 invoice reached the supplier ledger but is missing from ours. Verify invoice then Dr purchases / Cr payables $400.","trap":"Do not adjust the ledger for an invoice that genuinely belongs to a different supplier.","check":"A supplier credit note appears in our books but not on the supplier statement. What explains the difference?","answer":"A timing difference; our payable may be lower until the supplier processes that credit note."},"FA2:F1":{"paper":"FA2","code":"F1","summary":"A trial balance lists ledger debit and credit balances to check arithmetical equality. Agreement does not prove all transactions are correct.","steps":["Draw balances from each general ledger account at a particular date.","Put assets and expenses mainly on the debit side; income, liabilities and capital mainly on the credit side.","Investigate when debit and credit totals differ; a suspense account may temporarily capture an unresolved difference."],"formula":"Trial balance debit total = Trial balance credit total.","example":"Cash $2,000 Dr, receivables $4,000 Dr, expenses $1,000 Dr, payables $2,000 Cr and capital $5,000 Cr: both sides $7,000.","trap":"Errors of omission, original entry, complete reversal and principle may leave a balanced trial balance.","check":"Does a balanced trial balance prove sales are complete?","answer":"No; entire omitted transactions can leave both sides equal."},"FA2:F2":{"paper":"FA2","code":"F2","summary":"Errors need correction according to which side and amount was misstated. Suspense accounts only arise when the trial balance did not originally agree.","steps":["For an error of principle, reverse the wrong classification and post the correct account.","For a single-sided omission, post the missing debit or credit against suspense if the temporary balancing entry already exists.","For complete double-entry errors, correct both substantive accounts; no suspense may be needed."],"formula":"Correcting journal = Reverse incorrect effect + Record correct treatment.","example":"Office equipment $900 was debited to repairs instead of non-current assets (credit bank correct). Correction: Dr office equipment $900 / Cr repairs $900.","trap":"The wrong amount being posted equally to both sides is an error of original entry and does not unbalance the trial balance.","check":"A cash receipt of $600 is correctly debited to bank but credited to receivables by only $60. Which type?","answer":"Single-sided numerical error causing a $540 trial balance discrepancy; correct the credit side."},"FA2:G1":{"paper":"FA2","code":"G1","summary":"Prepare basic statements from adjusted ledger balances. Adjust for depreciation, accruals, prepayments and closing inventory before computing profit.","steps":["A statement of profit or loss reports revenue less cost of sales and expenses.","A statement of financial position reports assets, liabilities and equity at the reporting date.","For incomplete records, reconstruct missing revenue, purchases or cash using control accounts, margins and changes in net assets."],"formula":"Gross profit = Net revenue − Cost of sales; Profit = Gross profit − Operating expenses ± Other items.","example":"Revenue $50,000, returns $2,000; opening inventory $5,000, purchases $24,000, closing inventory $7,000. Net revenue $48,000; cost of sales $22,000; gross profit $26,000.","trap":"Loan proceeds and additional owner capital are not revenue, even when they increase bank.","check":"If opening net assets $25,000, closing $35,000, drawings $3,000 and new capital $5,000, profit?","answer":"$8,000 = 35,000 − 25,000 + 3,000 − 5,000."},"FA2:H2":{"paper":"FA2","code":"H2","summary":"A partnership allocates profit between partners according to their agreement and records each partner's capital and current account movements.","steps":["Calculate profit before appropriations in the ordinary statement of profit or loss.","Allocate partnership salary, interest on capital, interest on drawings and the remaining profit share through a profit appropriation account.","Keep fixed capital accounts separate from current accounts if fixed-capital method is used."],"formula":"Residual profit = Profit − Salaries − Interest on capital + Interest on drawings.","example":"Profit $20,000; salary to A $4,000; remainder split A:B 3:2. Remaining $16,000 gives A $9,600 and B $6,400; A total allocation $13,600.","trap":"Partner salaries are normally appropriations of profit, not staff wages within operating expenses.","check":"If a profit-sharing ratio is not specified, what should you check?","answer":"Apply the actual partnership agreement and the applicable rules rather than assuming an invented ratio."},"MA2:A3":{"paper":"MA2","code":"A3","summary":"Good cost classification makes costing, budgets and decisions comparable. The same cost can have more than one classification.","steps":["Direct cost is traceable to a cost object; indirect cost must be allocated or absorbed.","Fixed cost is constant in total within the relevant range; variable cost changes with activity.","Relevant costs are future incremental cash flows that differ between alternatives. Sunk costs are not relevant."],"formula":"Total cost = Total fixed cost + Variable cost per unit × Activity.","example":"Fixed rent $3,000 plus $8/unit variable materials at 400 units gives total $6,200.","trap":"A fixed cost is not necessarily irrelevant: a future fixed cost that differs by decision is relevant.","check":"Is last month's non-refundable machine purchase relevant to today's special order decision?","answer":"No; it is a sunk cost."},"MA2:B1":{"paper":"MA2","code":"B1","summary":"Material costing tracks receipts, issues, inventory and related purchase decisions. Select methods carefully when prices change.","steps":["FIFO issues earliest inventory first; periodic weighted average divides total available cost by units.","EOQ balances ordering and holding costs for a stable demand scenario.","Reorder level considers demand during the lead time; add buffer if the question requires safety stock."],"formula":"EOQ = √(2 × Annual demand × Order cost ÷ Annual holding cost/unit).","example":"Demand 10,000 units; order cost $40; holding cost $2/unit/year. EOQ = √(800,000/2) ≈ 632 units.","trap":"EOQ is an order quantity, not a reorder level; some exams supply factors/formulae as needed.","check":"Available inventory: 100 @ $3 and 100 @ $5. Periodic weighted average?","answer":"$4 per unit."},"MA2:B2":{"paper":"MA2","code":"B2","summary":"Labour cost includes wages, overtime premiums, bonuses and employer expenses. Productivity differences affect both direct labour cost and overhead.","steps":["Gross pay = basic pay + overtime + bonuses; net pay deducts employee contributions and deductions.","Use time cards, job cards and payroll records to split direct production time from indirect time.","Labour turnover indicates workforce movement; be precise about the denominator provided."],"formula":"Labour turnover (replacement basis) = Replacements ÷ Average employees × 100%.","example":"Average employees 80, replacements 12 in year: labour turnover = 15% using replacement basis.","trap":"Do not treat employee deductions as extra employer labour cost; gross wages already include them.","check":"A worker earns $12/hour for 40 hours and double-rate for 5 overtime hours. Gross wage?","answer":"40×12 + 5×24 = $600."},"MA2:B3":{"paper":"MA2","code":"B3","summary":"Production overheads are indirect manufacturing costs. Use allocation, apportionment and absorption to charge costs to outputs.","steps":["Allocate whole costs directly to the relevant cost centre, apportion shared costs on rational bases, and reapportion service department costs.","Calculate a predetermined overhead absorption rate (OAR) from budgeted overhead and budgeted activity.","Over-absorption arises when absorbed overhead exceeds actual overhead; under-absorption arises when it falls short."],"formula":"OAR = Budgeted production overhead ÷ Budgeted activity.","example":"Overhead budget $48,000, machine hours 8,000 → $6 per machine hour. Job using 15 hours absorbs $90 overhead.","trap":"The cost centre that incurs overhead is not necessarily the final product cost object.","check":"If absorbed overhead is $52,000 but actual overhead $49,000, over/under?","answer":"$3,000 over-absorbed."},"MA2:C1":{"paper":"MA2","code":"C1","summary":"Absorption costing treats fixed production overhead as part of product cost. Profit differs from marginal costing when inventory changes.","steps":["Product cost includes direct materials, direct labour, variable manufacturing overhead and absorbed fixed manufacturing overhead.","Apply normal-cost overhead using an appropriate budgeted activity base.","Fixed production overhead held in closing inventory delays expense recognition; inventory growth often raises absorption profit relative to marginal profit."],"formula":"Absorption product cost/unit = Variable production cost/unit + Fixed production OAR/unit.","example":"Variable production $12/unit and fixed production overhead $60,000 for 10,000 normal units → absorption cost $18/unit.","trap":"Selling and administration expenses are period costs, not product inventory.","check":"Inventory rises by 800 units and fixed production overhead rate is $4/unit. Profit difference?","answer":"Absorption profit exceeds marginal profit by $3,200, all else equal."},"MA2:C2":{"paper":"MA2","code":"C2","summary":"Marginal costing values inventory at variable production cost and charges fixed production overhead in full to the period.","steps":["Contribution = sales less variable costs; it covers fixed costs and then profit.","Closing inventory excludes fixed production overhead under marginal costing.","Reconcile marginal and absorption profit differences using the change in inventory units × fixed production overhead per unit."],"formula":"Profit = Total contribution − Fixed costs.","example":"Selling price $25, variable production and selling cost $15/unit. At 2,000 units, contribution $20,000; fixed costs $12,000; profit $8,000.","trap":"A profit-margin percentage uses sales as denominator; a mark-up percentage uses cost.","check":"If sales are $5,000 and variable costs $3,200, what is contribution?","answer":"$1,800."},"MA2:C3":{"paper":"MA2","code":"C3","summary":"Job costing accumulates costs for a specific job; batch costing accumulates for a group of identical items.","steps":["Collect direct material, direct labour and applied production overhead on job/batch cost cards.","Add profit using either mark-up on cost or margin on selling price — not interchangeably.","Cost per unit in batch costing = total batch cost ÷ good units produced."],"formula":"Selling price for 30% margin = Cost ÷ 0.70.","example":"A job costs $1,400 and needs a 30% profit margin on selling price: selling price = $2,000, profit $600.","trap":"Adding 30% to cost creates a mark-up, not a 30% margin.","check":"A batch costs $4,500 and contains 150 good units. Cost/unit?","answer":"$30."},"MA2:C4":{"paper":"MA2","code":"C4","summary":"Process costing follows mass production across processes, including work in progress, losses and jointly produced outputs.","steps":["Expected normal loss is part of the costing process; abnormal loss or gain is analysed separately.","Equivalent units convert partially completed WIP into a comparable finished-unit amount.","Where joint products arise, split joint processing cost on the basis specified (output volume or sales value at split-off). By-product receipts may be deducted from joint costs if the question specifies that treatment."],"formula":"Equivalent units = Completed units + WIP units × % completion (for the specific cost element).","example":"400 completed units plus 100 closing WIP units 60% complete for conversion costs = 460 conversion equivalent units.","trap":"Do not use the same completion percentage for materials and conversion unless the question states it.","check":"2 joint products split joint costs $60,000 in relative sales values 2:1. Allocation?","answer":"$40,000 to the first and $20,000 to the second."},"MA2:C5":{"paper":"MA2","code":"C5","summary":"Service costing calculates unit cost for services such as transport, hotels and hospitals using an appropriate composite unit.","steps":["Identify cost per unit of service, such as tonne-km, passenger-km or occupied bed-day.","Calculate composite output correctly before dividing total service cost.","Separate fixed capacity costs and variable activity costs where the decision requires it."],"formula":"Transport cost per tonne-km = Total transport cost ÷ (Tonnes carried × Kilometres travelled).","example":"A truck carries 8 tonnes for 150 km. Service output = 1,200 tonne-km. Cost $2,400 gives $2/tonne-km.","trap":"A tonne-km is not the same as tonnes plus kilometres; multiply, do not add.","check":"A bus carries 20 passengers for 40 km. Output?","answer":"800 passenger-km."},"MA2:D1":{"paper":"MA2","code":"D1","summary":"Cost-volume-profit (CVP) analysis links sales, costs and profit within a relevant range. Break-even occurs where total contribution equals fixed costs.","steps":["Contribution per unit = selling price minus variable cost per unit.","Break-even units = fixed costs divided by contribution per unit; round up where necessary.","Margin of safety compares expected activity with break-even activity; C/S ratio relates contribution to sales."],"formula":"Break-even units = Fixed cost ÷ Contribution/unit; C/S ratio = Contribution ÷ Sales.","example":"Price $50; variable cost $30; fixed cost $12,000. Contribution $20/unit, break-even 600 units. At 850 units, margin of safety = 250 units.","trap":"Margin of safety % usually uses budgeted/actual sales as denominator, not break-even sales.","check":"Contribution per unit $15, fixed costs $9,000, expected sales 1,000 units. Break-even and MOS?","answer":"600 units break-even; 400 units margin of safety (40%)."},"MA2:D2":{"paper":"MA2","code":"D2","summary":"Short-term decisions should compare future costs and benefits that change between alternatives, subject to capacity or resource constraints.","steps":["Ignore sunk and committed past expenditures that cannot be changed.","Include opportunity cost when using scarce resources; if a resource is in shortage, rank products by contribution per limiting factor unit.","Special orders may be accepted below normal price when incremental contribution is positive and no important opportunity costs are omitted."],"formula":"Contribution per limiting unit = Contribution per product ÷ Scarce resource units per product.","example":"Product A contributes $18 and needs 3 machine hours → $6/hour. Product B contributes $14 and needs 2 hours → $7/hour, so B ranks first if machine time is scarce.","trap":"Do not automatically include absorbed fixed overhead in a short-term incremental decision.","check":"What is the relevant cost of an idle material with zero alternative use and no resale value?","answer":"Its opportunity cost may be zero, assuming no extra disposal or replacement cost."},"MA2:D3":{"paper":"MA2","code":"D3","summary":"Investment appraisal compares the timing and size of future project cash flows. Distinguish discounted methods from non-discounted methods.","steps":["Payback measures time to recover initial investment but normally ignores cash flows after payback and the time value of money.","NPV discounts relevant future net cash flows at the cost of capital and subtracts the initial outlay.","Use only future incremental cash flows, including relevant working capital, disposal and tax where specified."],"formula":"NPV = Σ Cash flow at t ÷ (1+r)^t − Initial investment.","example":"Invest $10,000; receive $6,000 at end of each of two years; discount rate 10%. NPV ≈ 6,000/1.1 + 6,000/1.1² − 10,000 = $413.","trap":"Accounting profit is not the same as project cash flow; depreciation is a non-cash charge.","check":"A project has positive NPV. What does that indicate?","answer":"It is expected to earn above the assumed required return under the model's assumptions."},"MA2:E3":{"paper":"MA2","code":"E3","summary":"A cash budget forecasts actual receipts and payments to highlight potential cash surpluses or funding shortages.","steps":["Convert credit sales and purchases into the periods when cash is expected to be received or paid.","Include capital expenditure, tax and finance payments at their cash dates, not their profit or loss dates.","Closing cash = opening cash + receipts − payments; an overdraft is a negative closing cash balance."],"formula":"Closing cash = Opening cash + Total receipts − Total payments.","example":"Opening bank $1,400; collections $8,000; payments $9,900 → forecast closing overdraft $500.","trap":"Depreciation is an expense but not a cash payment in the cash budget.","check":"If customers pay one month after sale, where does October's credit sale appear?","answer":"Normally in November cash receipts, assuming no bad debts and full one-month delay."},"MA2:E4":{"paper":"MA2","code":"E4","summary":"Businesses can invest excess cash or arrange finance to cover working-capital needs. Match the funding method to the risk, cost and duration.","steps":["Trade credit and overdrafts are often short-term financing; loans and equity can finance longer-term operations.","Effective borrowing cost depends on interest, fees, timing and security.","Cash invested is not automatically profit: interest earned and principal returned are different cash flows."],"formula":"Net interest = Principal × Interest rate × Time (for simple-interest examples).","example":"$10,000 deposited for three months at 4% simple annual interest earns $100.","trap":"An overdraft is a financing arrangement and current liability, not revenue.","check":"Would a long-lived machine normally be financed exclusively with a continuously rolled-over overdraft?","answer":"It creates refinancing and liquidity risk; match longer-lived investment to appropriate longer-term funding."},"FA1:A1":{"paper":"FA1","code":"A1","summary":"Recording financial transactions begins by identifying the type of event and the evidence that it occurred.","steps":["Separate cash transactions, credit transactions, capital contributions, drawings and transfers.","Decide whether a transaction changes an asset, liability, equity, income or expense.","Record only business transactions, not the owner's personal spending as business expense."],"formula":"Assets = Liabilities + Equity.","example":"Owner invests $3,000 in business bank: assets rise $3,000 and equity rises $3,000.","trap":"Sales revenue is different from cash received from a bank loan.","check":"Does paying a supplier reduce profit?","answer":"No; paying an existing payable reduces bank and payable. The purchase was recognised separately."},"FA1:A2":{"paper":"FA1","code":"A2","summary":"Source documents provide an audit trail for transactions and support the bookkeeping entries made.","steps":["Invoice requests payment and documents a sale or purchase.","Credit note reduces an earlier invoice; debit note may request correction or support a return.","Receipt evidences payment; purchase order authorises ordering but does not by itself create a payable."],"formula":"Accounts payable is normally supported by supplier invoices after goods/services are received.","example":"A business returns faulty goods, and the supplier issues a $500 credit note. Reduce purchase/payable balances according to the original transaction.","trap":"A quotation or purchase order alone is not proof that goods were supplied.","check":"What document normally reduces a customer's invoice after a sales return?","answer":"A sales credit note."},"FA1:B1":{"paper":"FA1","code":"B1","summary":"Double entry is a recording system in which each transaction creates equal debits and credits.","steps":["Asset and expense increases are debits; liability, income and capital increases are credits.","A debit is not necessarily 'good' and a credit is not necessarily 'bad'.","Post both sides even when accounts belong to different ledger systems."],"formula":"Debits = Credits.","example":"Credit sale of $900: Dr trade receivables $900; Cr sales revenue $900.","trap":"An increase in liability is usually a credit, even though it may feel like something owed.","check":"Borrow $4,000 from the bank. Double entry?","answer":"Dr bank $4,000 / Cr loan payable $4,000."},"FA1:B2":{"paper":"FA1","code":"B2","summary":"A journal lists the accounts, amounts and narration for a non-routine or correcting transaction.","steps":["Use a dated journal and clearly state both debit and credit accounts.","Keep an equal total on each side before posting the journal to the general ledger.","A correction that merely reclassifies an expense does not create a second bank payment."],"formula":"Total journal debits = Total journal credits.","example":"Insurance of $250 debited to repairs accidentally: correction Dr insurance $250 / Cr repairs $250.","trap":"Do not post the original transaction again in full unless reversing the wrong entry first.","check":"How to reclassify $100 from office expense to motor expense?","answer":"Dr motor expense $100 / Cr office expense $100."},"FA1:C1":{"paper":"FA1","code":"C1","summary":"The banking process supports receiving and making payments safely through cash, card, cheque, transfer and electronic systems.","steps":["Bank clearing settles payments among banks; transfer speed and processing controls depend on payment method.","Segregation of duties, approval limits and secure credential management reduce payment error and fraud.","Bank statements are independently issued records that help validate the business cash book."],"formula":"No special equation: focus on bank services, authorisations and documentation.","example":"A staff member prepares a transfer; a different authorised manager approves it before release.","trap":"Do not confuse a card authorisation with final bank settlement.","check":"Why is a separate payment approver useful?","answer":"It reduces the risk that one person can both initiate and authorise an inappropriate payment."},"FA1:D1":{"paper":"FA1","code":"D1","summary":"Payroll records wages earned, employee deductions and payments to staff and relevant authorities.","steps":["Calculate gross wages from hourly rates, piece work, salaries and overtime conditions.","Employee deductions reduce net pay, but usually remain part of gross payroll cost.","Employer contributions may add to payroll cost where specified."],"formula":"Net pay = Gross pay − Employee deductions.","example":"40 hours at $10/hour plus 5 overtime hours at $15/hour: gross $475. Deductions $60 give net pay $415.","trap":"Overtime premium is not always the full overtime pay; distinguish the basic rate from premium.","check":"A worker earns $620 gross and deductions total $75. Net pay?","answer":"$545."},"FA1:E1":{"paper":"FA1","code":"E1","summary":"General ledger accounts accumulate each account's debit and credit movements and are balanced at reporting dates.","steps":["Post transactions from source records or journals to the right side of the relevant ledger account.","Use totals and a balancing figure to find the balance carried down.","Remember that bank and receivables normally have debit balances, while sales and payables normally have credits."],"formula":"Closing debit balance = Opening debit balance + debits − credits.","example":"Bank starts $2,000; receives $3,000; pays $1,100. Closing debit balance = $3,900.","trap":"The account's balance carried down appears on the smaller side purely to make ledger columns agree.","check":"Bank starts $500 and receives $300 but pays $900. Closing state?","answer":"$100 bank overdraft (credit balance)."},"FA1:F1":{"paper":"FA1","code":"F1","summary":"Maintain cash records promptly so the business knows available funds and can check against bank statements.","steps":["Record each cash receipt and payment with reference to supporting documents.","Post bank and cash separately where the question distinguishes them.","Use regular cash counts and bank reconciliation to catch omissions and transposition errors."],"formula":"Closing cash = Opening cash + Cash received − Cash paid.","example":"Opening cash $600, petty sales receipts $180 and cash payments $250 give closing cash $530.","trap":"Cash in hand cannot normally have a negative physical balance; a negative bank balance is an overdraft.","check":"If cash receipts are understated by $40, does cash book show too much or too little cash?","answer":"Too little cash by $40."},"FA1:F2":{"paper":"FA1","code":"F2","summary":"Imprest petty cash restores a fixed float after properly authorised petty expenses.","steps":["Set an imprest amount and support each payment with a voucher.","At replenishment, the amount paid into the petty cash box equals the approved expenditure since the previous top-up.","Separate the float cash from petty-cash expense categories to avoid double-counting."],"formula":"Cash remaining + Petty-cash vouchers = Imprest float.","example":"Imprest $200; receipts/vouchers record $65 of petty expenses; cash remaining $135. Reimburse $65.","trap":"Non-imprest methods do not aim to return the balance to one set float after every reimbursement.","check":"If vouchers total $37 out of an $100 imprest, how much is replenished?","answer":"$37."},"FA1:G1":{"paper":"FA1","code":"G1","summary":"The receivables ledger monitors customers who owe the business for credit sales.","steps":["Add credit sales and opening balances; subtract receipts, credit notes and write-offs.","Use customer-by-customer records to reconcile the trade receivables control balance.","Distinguish trade receivables from sales revenue, which is an income account."],"formula":"Closing receivables = Opening + Credit sales − Receipts − Sales returns − Write-offs.","example":"Opening $5,000, credit sales $8,000, receipts $7,000, returns $500: closing receivables $5,500.","trap":"Cash sales do not increase trade receivables.","check":"Customer settles a $450 invoice by bank transfer. Entry?","answer":"Dr bank $450 / Cr receivables $450."},"FA1:H1":{"paper":"FA1","code":"H1","summary":"Trade payables record supplier balances outstanding for goods or services bought on credit.","steps":["Add credit purchases; deduct payments and supplier credit notes.","Compare the general ledger control total to supplier-level records.","Purchase returns are not the same as sales returns."],"formula":"Closing payables = Opening + Credit purchases − Cash paid − Purchase returns.","example":"Opening payables $2,000, new credit purchases $3,300, payment $2,500, return $200: closing payable $2,600.","trap":"Payment for a new cash purchase does not settle an existing trade payable unless there was an invoice on credit.","check":"Supplier allows a $70 return. Entry?","answer":"Dr payables $70 / Cr purchase returns $70 (or inventory/appropriate account)."},"FA1:I1":{"paper":"FA1","code":"I1","summary":"Reconciliations compare two independent records of a balance, distinguish errors from timing differences, and justify correcting entries.","steps":["Cash-book/bank-statement differences arise from unpresented cheques, lodgements in transit or bank entries not recorded.","Control-account reconciliations investigate inconsistencies with individual customer/supplier accounts.","Make ledger corrections for real errors; do not post timing reconciling items twice."],"formula":"Reconciled record A = Reconciled record B after adjustments and timing items.","example":"Cash book $1,500; unpresented cheque $200: bank statement can show $1,700 while payment is still outstanding.","trap":"An unpresented cheque has already been posted in the cash book.","check":"Is a standing order seen only on the statement a timing item?","answer":"No; update the cash book and corresponding expense/liability account."},"FA1:J1":{"paper":"FA1","code":"J1","summary":"A trial balance helps verify that total debits equal total credits after posting the ledger accounts.","steps":["Extract each account's closing balance as at the date.","Debits normally include assets and expenses; credits normally include capital, income and liabilities.","Trial balance agreement is only an arithmetical check, not proof that accounting treatment is right."],"formula":"Σ Debit balances = Σ Credit balances.","example":"Debit: cash $400 and expenses $600. Credit: sales $700 and payable $300. Both sides $1,000.","trap":"Omitted transactions and equal double-entry misclassifications can evade this test.","check":"Does a balanced trial balance detect a machine wrongly charged to repairs?","answer":"Not necessarily; both sides may still balance."},"FA1:J2":{"paper":"FA1","code":"J2","summary":"Error correction distinguishes mistakes that affect the trial balance from those that leave it balanced.","steps":["A one-sided posting usually causes trial balance disagreement.","An error of principle or complete omission may leave totals equal.","Correct the accounts and suspense balance if one was used; give a narration."],"formula":"Correction = Remove wrong effect + Record right effect.","example":"A $400 revenue credit was omitted while receivables debit was correctly posted. If suspense was credited $400 to balance, correct: Dr suspense $400 / Cr sales $400.","trap":"Do not create a new sale entry if the receivables debit is already correct.","check":"A purchase invoice of $300 is completely omitted. Does trial balance disagree?","answer":"No; both debit and credit are absent."},"MA1:A2":{"paper":"MA1","code":"A2","summary":"Management information is prepared mainly for internal planning, control and decisions, rather than only for published reporting.","steps":["Information should be relevant, reliable, understandable, timely and cost-effective.","Managers use operational, tactical and strategic information at different levels.","Management reports can use estimates and non-financial measures where useful."],"formula":"Value of information depends on whether better decisions justify its collection and processing cost.","example":"A production supervisor needs daily defect rates; a board may need multi-year investment returns.","trap":"Information that arrives after the decision date may be accurate but not useful.","check":"Is a daily machine-breakdown log typically operational or strategic?","answer":"Operational information."},"MA1:B1":{"paper":"MA1","code":"B1","summary":"Transaction processing systems capture routine business events and can feed management information systems.","steps":["Inputs must be checked for validity, completeness and proper authorisation.","Processing converts inputs to structured records; outputs provide summaries and exception reports.","Access controls, backups and audit trails protect records."],"formula":"Input → Processing → Output + Controls.","example":"A POS system records quantities sold, updates inventory and creates daily sales summaries.","trap":"An exception report shows unusual items, not every ordinary transaction.","check":"Why validate quantity entered as non-negative?","answer":"To catch input errors before they contaminate stock and management reports."},"MA1:B2":{"paper":"MA1","code":"B2","summary":"Coding systems identify transactions, products, customers and departments consistently so information can be retrieved and summarised.","steps":["Sequential codes are numbered in order of issue.","Hierarchical codes embed categories and sub-categories; block codes allocate ranges to each group.","A good code has enough capacity for future items and should reduce ambiguity."],"formula":"Example hierarchical code: 02-04-015 = division 02, department 04, item 015.","example":"A company allocates 100–199 to raw materials and 200–299 to finished goods: block coding.","trap":"A sequential code does not by itself reveal a product's category.","check":"What distinguishes a hierarchical code?","answer":"Its parts correspond to organisational or product classification levels."},"MA1:C1":{"paper":"MA1","code":"C1","summary":"Cost behaviour is an essential starting point for calculating product costs, forecasting budgets and evaluating decisions.","steps":["Variable cost changes in total with activity but often remains constant per unit.","Fixed cost stays constant in total within the relevant range but falls per unit when volume rises.","Semi-variable costs contain fixed and variable portions; high-low estimates the variable rate from two activity observations."],"formula":"High-low variable cost/unit = (High cost − Low cost) ÷ (High units − Low units).","example":"At 2,000 units total cost $13,000; at 5,000 units $22,000. Variable rate $3/unit; fixed cost $7,000.","trap":"Use observations with the highest and lowest activity, not highest and lowest cost.","check":"Predicted total at 6,000 units using this example?","answer":"$7,000 + 6,000×$3 = $25,000."},"MA1:C2":{"paper":"MA1","code":"C2","summary":"Cost units measure output, while cost centres identify organisational locations where costs are collected.","steps":["A cost centre accumulates costs (e.g. the machining department).","A profit centre controls revenue and cost; an investment centre also has responsibility for invested assets.","Composite service units combine measures, such as tonne-kilometres."],"formula":"Service unit examples: per patient-day, per passenger-km, per tonne-km.","example":"A delivery operation carries 6 tonnes for 80 km: output is 480 tonne-km.","trap":"Cost centre and cost unit are not synonymous; one is organisational, the other measures output.","check":"A branch manager controls profit and investment in equipment. Which centre?","answer":"Investment centre."},"MA1:D1":{"paper":"MA1","code":"D1","summary":"Material control balances purchase and storage costs with the risk of running out of materials.","steps":["Use goods received notes, materials requisitions and inventory records to track stock.","Classify direct materials as traceable to jobs, while indirect supplies form overhead.","FIFO uses oldest costs first; weighted average pools units and values as the costing method requires."],"formula":"Weighted average price = Total available inventory cost ÷ Total available units.","example":"Buy 50 units @ $4 and 50 @ $6: periodic weighted average $5/unit.","trap":"Under FIFO, physical movement need not be exactly the same as accounting cost flow.","check":"If 30 units are issued at the average price in the example, issue cost?","answer":"$150."},"MA1:D2":{"paper":"MA1","code":"D2","summary":"Labour accounting records time and output and attributes wages to products or overhead.","steps":["Time tickets record attendance; job cards assign time spent to particular jobs.","Direct labour is traceable to outputs; indirect labour supports production but cannot be traced economically.","Understand the difference between basic pay, overtime premium and idle-time cost."],"formula":"Gross wages = Normal-time pay + Overtime pay + Bonuses.","example":"38 normal hours @ $10 plus 2 hours overtime at $15 = $410 gross.","trap":"A non-production maintenance worker's wages can be factory overhead, not direct product labour.","check":"If 8 hours of a worker's 40-hour week are idle, should those hours be ignored?","answer":"No. Record idle time and classify its cost according to the stated accounting treatment."},"MA1:D4":{"paper":"MA1","code":"D4","summary":"Product cost information combines materials, labour and production overhead to estimate unit costs.","steps":["Direct materials + direct labour + direct expenses form prime cost.","Production cost adds appropriate production overhead.","Cost per unit is useful for inventory valuation and pricing, but selling price must also reflect market constraints."],"formula":"Prime cost = Direct materials + Direct labour + Direct expenses.","example":"Direct materials $1,400, labour $900, direct machine hire $100 and production overhead $600: production cost $3,000.","trap":"Avoid adding selling expenses into factory production cost when valuing inventory.","check":"A batch of 100 items costs $3,000 to produce. Unit production cost?","answer":"$30."},"MA1:E2":{"paper":"MA1","code":"E2","summary":"Spreadsheets organise accounting inputs and use formulas for calculations and reporting.","steps":["Cell references let formulas refer to data rather than hardcoding the answer.","Relative references move when copied; absolute references such as $B$2 remain fixed.","Use controls, input formatting, reasonableness checks and version discipline."],"formula":"Example Excel formula: =SUM(B2:B20), or =C2*$B$1.","example":"A VAT rate is stored in B1 and selling price in C2. Use =C2*$B$1 to keep the tax-rate reference fixed when copied down.","trap":"A spreadsheet showing #### may only need a wider column, not a corrected formula.","check":"How do you sum values in cells E4 to E12?","answer":"=SUM(E4:E12)."},"FA1:A3":{"paper":"FA1","code":"A3","summary":"Accounting systems process documents into journals, ledgers and financial reports through controlled and repeatable workflows.","steps":["Identify source documentation and the person who authorises it.","Enter the transaction once, using the required ledger coding and double-entry logic.","Review control totals, exception reports, permissions and audit trails before reporting results."],"formula":"Documents → Transaction record → Journal/ledger → Trial balance → Reports.","example":"A customer invoice starts as a sales source document, creates a credit sales entry and updates both the customer account and the general ledger.","trap":"A sale shown in a spreadsheet is not automatically posted to the official ledger.","check":"Why reconcile totals after importing invoices into a system?","answer":"To confirm all authorised invoices were captured once and for the correct values."},"FA1:B3":{"paper":"FA1","code":"B3","summary":"The financial statements communicate how much the business owns and owes and whether trading activities earned profit.","steps":["The statement of financial position groups assets, liabilities and equity at a point in time.","The statement of profit or loss groups income and expenses over a period.","Understand links: profit increases equity, drawings reduce equity, and loans create liabilities."],"formula":"Assets − Liabilities = Equity.","example":"If equipment is $8,000, bank $2,000 and liabilities $3,000, net assets/equity $7,000.","trap":"A loan received increases bank but is not trading income.","check":"A credit sale increases what two financial statement elements initially?","answer":"Receivables (asset) and sales income, which will increase profit and equity."},"FA1:C2":{"paper":"FA1","code":"C2","summary":"Document retention supports audits, customer service, legal compliance and correction of accounting records.","steps":["Apply a written policy covering documents, storage location, access rights and retention periods.","Preserve legibility and an audit trail even when records are digital.","Dispose of expired records securely; legal retention rules depend on jurisdiction and document type."],"formula":"Document control = Capture + Secure storage + Retrieval + Approved disposal.","example":"An invoice stored with date, supplier ID and unique invoice number can be retrieved during a supplier dispute.","trap":"There is no universal fixed retention period for every business and country; do not invent one in an exam.","check":"Why restrict payroll record access?","answer":"Because pay and deduction information is confidential and vulnerable to misuse."},"FA1:I2":{"paper":"FA1","code":"I2","summary":"A cash-book to bank-statement reconciliation distinguishes unrecorded ledger items from deposits and cheques that have not cleared.","steps":["Update the cash book for bank-only charges, standing orders and direct receipts.","Mark transactions already matching on both records.","Use outstanding lodgements and unpresented cheques to explain any remaining difference."],"formula":"Bank statement balance = Corrected cash book − Lodgements in transit + Unpresented cheques (for positive debit bank balances).","example":"Corrected cash-book $1,700, outstanding lodgement $250, unpresented cheque $150 gives statement balance $1,600.","trap":"Do not post timing items again: they already appear in the cash book.","check":"A cheque paid $200 appears only in the cash book. What kind of difference?","answer":"Unpresented cheque, if not yet processed by the bank."},"FA1:I3":{"paper":"FA1","code":"I3","summary":"Reconcile individual supplier accounts so the purchasing records agree with supplier invoices, credits and payments.","steps":["Compare supplier balance with the latest supplier statement as at the same date.","Match invoices, credit notes, payments and discounts by reference.","Adjust your records for actual omissions or errors; keep timing items documented."],"formula":"Opening payable + Credit purchases − Payments − Credits = Closing payable.","example":"Supplier statement $1,250 includes a $100 invoice not recorded locally. Verify and post Dr purchases/inventory / Cr supplier $100, then reconcile.","trap":"Do not automatically treat every difference as supplier fraud or an accounting error.","check":"If payment is in our ledger but not yet on supplier statement, should it be entered again?","answer":"No. Treat it as a timing difference if correctly recorded."},"MA1:A1":{"paper":"MA1","code":"A1","summary":"Organisations collect transaction data through accounting systems to plan resources and control operations.","steps":["Identify business functions such as purchasing, production, sales and finance.","Financial accounting mainly serves external reporting; management accounting supports internal decisions.","Information systems transform transactions into reports subject to controls and authorisation."],"formula":"Business event → Source document → Processing → Management report.","example":"A store's point-of-sale transactions feed daily sales, stock replenishment and departmental reports.","trap":"A sales forecast is not a historical financial transaction; it is management information.","check":"Who primarily uses a weekly labour efficiency report?","answer":"Internal production and operations managers."},"MA1:D3":{"paper":"MA1","code":"D3","summary":"Other expenses include indirect production expenses and non-production costs; classify them before calculating total product or service costs.","steps":["Factory rent and power may be production overhead, while marketing and office administration are non-production costs.","Allocate direct expenses where traceable and apportion shared overheads using sensible bases.","The chosen method should be applied consistently and explained."],"formula":"Total manufacturing cost = Prime cost + Production overhead.","example":"Factory power $2,000 split between departments based on machine hours 60:40 → $1,200 and $800.","trap":"Office marketing costs should not be absorbed into inventory production cost merely because the firm has products.","check":"What is the difference between cost allocation and apportionment?","answer":"Allocation charges an identifiable cost directly to one centre; apportionment splits a shared cost."},"MA1:E1":{"paper":"MA1","code":"E1","summary":"Spreadsheets offer flexible grids of cells for data input, arithmetic, charts and management reporting.","steps":["Worksheets contain rows, columns and cells; workbooks may contain multiple sheets.","Separate input values, formulas and reporting outputs to make the model auditable.","Use validation and version controls because spreadsheet flexibility increases error risk."],"formula":"Cell addresses: B7 is relative, $B$7 absolute, B$7 fixes only the row.","example":"A costing workbook stores sales units on one sheet and computes revenue on another.","trap":"Charts are not a substitute for correct formulas or checked source data.","check":"What should you check first when a calculated cell shows #DIV/0!?","answer":"Check whether its denominator refers to zero or an empty cell."},"MA1:E3":{"paper":"MA1","code":"E3","summary":"Present spreadsheet results in formats that decision makers can read, print and compare accurately.","steps":["Format dates, units, percentages and currency consistently.","Use appropriate chart types and labels, rather than decorative three-dimensional effects.","Set print areas, orientation, page breaks and scaling to keep headings visible."],"formula":"Percentage change = (New − Old) ÷ Old × 100%.","example":"Monthly sales comparisons may use a bar chart with clear month names and $ units.","trap":"A misleading axis can exaggerate differences even when source values are correct.","check":"What print-setting change can help a wide table fit on a page?","answer":"Landscape orientation, suitable scaling or a defined print area, with legibility checked."},"FA2:A2":{"paper":"FA2","code":"A2","summary":"Accounting records need an organised audit trail from transaction evidence to published financial statements.","steps":["Maintain complete and timely documentation, ledgers and supporting reconciliations.","Control access and responsibilities so changes are authorised and traceable.","Use periodic review to identify omissions, incorrect classification and duplicated postings."],"formula":"Documents → Journals → Ledgers → Trial balance → Adjustments → Financial statements.","example":"A monthly process imports supplier invoices, reconciles them to payables and then prepares the adjusted trial balance.","trap":"Cloud storage is not an automatic guarantee of integrity, backup or correct accounting.","check":"Why should changes to journal entries have audit trails?","answer":"To identify who made a correction, when, and on what authority."},"FA2:A3":{"paper":"FA2","code":"A3","summary":"Financial reporting standards and the conceptual framework guide recognition, measurement and presentation, subject to the paper's examinable documents.","steps":["Apply the definitions and recognition principles for assets, liabilities, income and expenses.","Consider useful information: relevance, faithful representation, comparability, verifiability, timeliness and understandability.","Consult ACCA's current examinable-documents list for which IFRS requirements are in scope."],"formula":"Assets = Equity + Liabilities; recognition and measurement depend on the applicable standards.","example":"A business receives customer money before delivering services; the present obligation typically makes it deferred income until earned.","trap":"A legal form alone does not always settle the accounting substance of an event.","check":"Does a balanced trial balance demonstrate compliance with IFRS?","answer":"No; recognition, measurement, classification and disclosures may still be wrong."},"FA2:B2":{"paper":"FA2","code":"B2","summary":"Accounting records move from supporting documents through journals and ledger balances into trial balances and statements.","steps":["Credit sales are recorded in receivables and revenue; credit purchases in relevant expenses/inventory and payables.","Journal entries adjust the ledger for year-end accruals, depreciation, write-offs and corrections.","Trial balance totals must be equal, but substantive controls remain necessary."],"formula":"Each transaction has equal debit and credit values.","example":"Credit purchase $900: Dr inventory or purchases $900 / Cr trade payables $900. Pay later: Dr payables / Cr bank.","trap":"The payable payment should not be counted as a second purchase expense.","check":"What is a control account used for?","answer":"It summarises subsidiary ledger transactions and enables reconciliation to detailed customer/supplier balances."},"FA2:H1":{"paper":"FA2","code":"H1","summary":"A partnership agreement determines how partners share profit, drawings and certain appropriations.","steps":["Read profit-sharing ratio, partner salaries, interest on capital, interest on drawings and other agreed rules.","Separate partner drawings from business operating expenses.","Where agreement is silent, use only the default rule specified by the applicable law or exam requirement."],"formula":"Amount allocated to partner = Share of residual profit + Any salary/interest allocations − Drawings in their current account.","example":"A profit-sharing ratio of 2:1 on residual profit $9,000 allocates $6,000 to A and $3,000 to B.","trap":"Partner salary in partnership appropriation is generally not an operating salary expense.","check":"Two partners agree to share profits 3:2. Profit after appropriations $25,000; share of B?","answer":"$10,000."},"FA2:H3":{"paper":"FA2","code":"H3","summary":"Changes in partnership membership require recalculating capital/current balances and adjusting profit shares from the effective date.","steps":["Calculate profit shares under the old agreement before any change and under the new agreement after it.","Record agreed adjustments to capital/current accounts and settlements.","Prepare partner disclosures and closing balances from reconciled ledger balances."],"formula":"Closing current account = Opening current + Profit allocation + Interest/salary credited − Drawings and charges.","example":"Partner A opens with current account $3,000 credit, receives $4,000 profit and draws $2,500: closing current balance $4,500 credit.","trap":"Do not apply a new profit-sharing ratio retrospectively without an explicit agreement.","check":"Why does the effective date of a partner joining matter?","answer":"Because the old and new partner groups may share profits over different portions of the accounting period."},"MA2:A1":{"paper":"MA2","code":"A1","summary":"Management information needs differ by role, decision and time horizon, so reports must be relevant and reliable.","steps":["Operational managers need frequent detailed controls; senior management uses aggregated trends and forecasts.","Timely and understandable information is more useful than late, unnecessarily elaborate reports.","Compare actual results with plans and investigate material differences."],"formula":"Variance = Actual − Budget (interpret direction according to cost or revenue).","example":"Budget production 1,000 units, actual 920: activity is 80 units below plan.","trap":"A favourable sales variance and a favourable cost variance use opposite sign interpretations.","check":"What information does a maintenance supervisor need for next week's schedule?","answer":"Recent breakdowns, forecast workloads, staffing and machine availability."},"MA2:A2":{"paper":"MA2","code":"A2","summary":"Cost accounting systems record and summarise material, labour and overhead for costing, budgets and decisions.","steps":["Choose a system appropriate to products: job, batch, process or service costing.","Trace direct materials and labour, then allocate and absorb indirect production overhead.","Keep cost accounting records reconcilable with financial accounting where required."],"formula":"Total production cost = Direct materials + Direct labour + Other direct expenses + Production overhead.","example":"For a customised furniture job: materials $1,000, labour $600, absorbed overhead $400 gives job cost $2,000.","trap":"A cost system's usefulness depends on its accuracy, classification and decision context, not just software sophistication.","check":"Why is overhead absorbed using an OAR?","answer":"To attribute shared production costs systematically to cost units using an appropriate activity base."},"MA2:A4":{"paper":"MA2","code":"A4","summary":"Cost and performance comparisons require like-for-like periods, appropriate baselines and an understanding of volume effects.","steps":["Separate price, quantity, mix and efficiency changes when information allows.","Adjust comparisons for activity levels rather than assuming all changes are performance effects.","Use both financial and non-financial measures to avoid a narrow assessment."],"formula":"Unit cost = Total relevant cost ÷ Units of comparable output.","example":"Cost rises from $10,000 for 1,000 units to $10,500 for 1,200 units. Unit cost falls from $10 to $8.75 despite higher total cost.","trap":"A higher total cost is not always evidence of reduced efficiency when output increased.","check":"Why compare cost per unit as well as total cost?","answer":"To distinguish activity-volume effects from changes in cost efficiency."},"MA2:A5":{"paper":"MA2","code":"A5","summary":"Management reports need clear presentation, traceable assumptions and timely exceptions so a manager can act on them.","steps":["Select tables, trends or charts appropriate to the decision.","Identify significant differences and possible causes rather than overwhelming the user with every raw transaction.","Label units, date ranges and data sources, especially forecasts versus actuals."],"formula":"A good report connects actual → comparison → explanation → action.","example":"A monthly manufacturing report flags material usage 12% above plan and suggests investigating scrap or inefficient processes.","trap":"Avoid presenting a simulated estimate as an observed fact.","check":"What should a decision-oriented variance report include besides the number?","answer":"Its cause, materiality and possible management response."},"MA2:E1":{"paper":"MA2","code":"E1","summary":"Cash differs from accounting profit because receipts and payments occur at different times from accruals and expenses.","steps":["Recognise immediate liquidity needs such as wages, materials, taxes and debt servicing.","Understand operating, investing and financing cash flow categories.","Plan to maintain sufficient liquidity without holding unnecessary idle balances."],"formula":"Net cash movement = Cash receipts − Cash payments.","example":"A company earns profit on credit sales but cannot pay suppliers until customers actually settle their balances.","trap":"Depreciation reduces accounting profit but does not itself reduce bank balance when charged.","check":"Can a profitable business still fail to pay wages?","answer":"Yes. Profit may be tied up in receivables or inventory while cash is insufficient."},"MA2:E2":{"paper":"MA2","code":"E2","summary":"Cash management involves collecting money efficiently, timing outflows, maintaining controls and investing genuine surpluses prudently.","steps":["Forecast short-term cash requirements and reconcile bank records.","Manage receivables, payables and inventory without harming vital relationships.","Consider security, liquidity and return when placing short-term cash deposits."],"formula":"Cash conversion cycle = Inventory days + Receivable days − Payable days (where examinable).","example":"Reducing collection time from 45 days to 30 days can release cash tied up in receivables, all else equal.","trap":"Paying suppliers late may improve short-term cash but risk fees, reputation or losing discounts.","check":"What distinguishes liquidity from profitability?","answer":"Liquidity is capacity to meet cash obligations as due; profitability reflects accounting revenues less expenses."},"BT:A2":{"paper":"BT","code":"A2","summary":"Stakeholders are individuals and groups affected by or able to influence an organisation. Their priorities can conflict, so managers must consider competing expectations when setting objectives.","steps":["Identify internal stakeholders, such as employees and directors, and external stakeholders, such as suppliers, customers, communities and regulators.","Consider each group's power, interest, legitimate expectations and potential impact on decisions.","Prioritise communication without assuming that every stakeholder has identical objectives."],"formula":"Stakeholder mapping: high power + high interest → engage closely.","example":"A supermarket considers customers' affordability, employees' wage conditions and suppliers' payment terms before revising its pricing strategy.","trap":"Shareholders are important stakeholders but not the only people affected by a business.","check":"Why might a regulator be high power but low day-to-day interest?","answer":"It can enforce standards, even when it rarely intervenes in normal operations."},"MA:C2":{"paper":"MA","code":"C2","summary":"Absorption and marginal costing use different treatments of fixed manufacturing overhead, affecting product cost and reported profit whenever inventory changes.","steps":["Under absorption costing, include fixed production overhead in inventory at an appropriate absorption rate.","Under marginal costing, charge all fixed production overhead to the period and value inventory using variable production costs.","Reconcile profit using the change in inventory units multiplied by fixed production overhead per unit."],"formula":"Absorption profit − Marginal profit = Inventory increase × Fixed production overhead per unit (ignoring other adjustments).","example":"Production 1,000 units, sales 800, fixed overhead absorbed at $5/unit: closing inventory rises by 200 units, so absorption profit is $1,000 higher than marginal profit, other factors equal.","trap":"Selling and administrative fixed costs are not inventoried in either approach.","check":"If inventory decreases by 300 units at a fixed overhead absorption rate of $4, which profit is higher?","answer":"Marginal costing profit exceeds absorption costing profit by $1,200, other things equal."},"FA:D4":{"paper":"FA","code":"D4","summary":"A tangible non-current asset is recognised at cost when it meets recognition requirements. Subsequent depreciation allocates depreciable amount across the periods that consume economic benefits.","steps":["Identify costs directly attributable to making the asset ready for intended use; exclude unrelated running costs.","Estimate useful life and residual value, and apply an appropriate depreciation method.","Review impairment, disposal and relevant reporting requirements rather than assuming carrying amount always equals market value."],"formula":"Straight-line depreciation/year = (Cost − Residual value) ÷ Useful life.","example":"Equipment purchase $21,000 plus delivery $1,000 and installation $2,000; residual $4,000; useful life five years. Capitalised cost $24,000 and depreciation $4,000/year.","trap":"Routine repair and maintenance ordinarily do not increase the cost of an existing asset.","check":"Does the equipment have a disposal gain if carrying amount is $8,000 and proceeds are $9,200?","answer":"Yes: recognise a $1,200 disposal gain before considering other disposal costs."},"LW:A1":{"paper":"LW","code":"A1","summary":"Corporate and business law questions depend on the examinable jurisdiction. This library currently indexes the Malaysia (MYS) syllabus, not a universal law syllabus.","steps":["Identify which institutions make legislation, adjudicate disputes and enforce legal obligations under the relevant jurisdiction.","Distinguish civil and criminal processes and understand the role of courts and dispute resolution.","Before answering a legal scenario, identify the source of law and the relevant legal relationship."],"formula":"Legal answer structure: Issue → Rule → Application → Conclusion.","example":"A business contract dispute generally raises private civil remedies, unlike regulatory prosecution for an offence; which court or remedy applies depends on the applicable rules.","trap":"Do not substitute United Kingdom company-law rules for a Malaysia (MYS) exam requirement.","check":"Why must an ACCA LW student check the examination variant?","answer":"Because legal concepts, statutory rules and examinable legislation differ across jurisdictions."},"PM:B1":{"paper":"PM","code":"B1","summary":"Activity-based costing (ABC) assigns production overhead according to the activities that generate costs instead of using only one volume-based rate.","steps":["Separate indirect costs into activity cost pools such as setups, inspections and machine processing.","Choose a sensible cost driver for each pool; divide pool cost by total driver activity to get a driver rate.","Charge products for the quantity of each driver they actually use and compare with traditional absorption."],"formula":"ABC cost driver rate = Activity cost pool ÷ Total cost driver units.","example":"Setup costs $36,000, 120 setups performed: setup driver rate $300/setup. Product A requires 18 setups, so receives $5,400 of setup overhead.","trap":"ABC may improve cost tracing but does not make every overhead cost variable or eliminate judgment in driver selection.","check":"How much setup overhead is allocated for 8 setups at $250 each?","answer":"$2,000 of setup overhead."},"TX:B2":{"paper":"TX","code":"B2","summary":"Malaysia TX questions on employment income require the examinable tax-year and jurisdiction rules. First classify receipts and benefits before applying any reliefs or deductions.","steps":["Identify monetary remuneration, benefits and employer-provided accommodation separately where relevant.","Determine whether particular items are taxable, exempt or subject to valuation under the examinable Malaysia rules.","Compute statutory and aggregate income following the official tax-year framework rather than importing outdated bands."],"formula":"Taxable employment income = Chargeable remuneration and benefits − Permitted employment deductions or exemptions (as applicable).","example":"A scenario gives salary, bonus and a benefit in kind. Classify the three items and consult the examinable valuation and exemption provisions before calculating a final taxable amount.","trap":"Do not apply a remembered Malaysian tax rate or relief from a different assessment year.","check":"Why are jurisdiction and assessment year essential to a TX computation?","answer":"Because thresholds, exemptions, reliefs and administrative rules can change from year to year."},"FR:B3":{"paper":"FR","code":"B3","summary":"An asset is impaired when its carrying amount exceeds the amount expected to be recovered from using or selling it, subject to the applicable accounting standard.","steps":["Identify the carrying amount from cost/revaluation less depreciation and prior impairment.","Compare it with recoverable amount, generally the higher of value in use and fair value less costs of disposal under IAS 36.","Recognise and allocate impairment correctly, including any special rules for cash-generating units."],"formula":"Impairment loss = Max(0, Carrying amount − Recoverable amount).","example":"A machine has carrying amount $90,000; value in use $68,000; fair value less costs of disposal $75,000. Recoverable amount $75,000; impairment $15,000.","trap":"Recoverable amount is the higher, not the lower, of the two recovery measurements.","check":"If carrying amount is $62,000 and recoverable amount $66,000, recognise an impairment?","answer":"No impairment is indicated by that comparison."},"AA:B3":{"paper":"AA","code":"B3","summary":"Audit risk is the risk an auditor gives an inappropriate opinion when financial statements are materially misstated. Audit planning links business risks to financial reporting assertions.","steps":["Identify potential misstatements from transactions, estimates, controls or the operating environment.","Distinguish inherent risk, control risk and detection risk at a conceptual level.","Describe the financial statement assertion affected and a specific audit response rather than writing a generic procedure."],"formula":"Audit risk = Risk of material misstatement × Detection risk (conceptual model).","example":"A client starts selling on credit to unfamiliar overseas customers. Revenue recognition and receivables valuation risk may rise. The audit team assesses controls and designs targeted substantive procedures.","trap":"An audit risk is not simply any business risk; connect it to a financial statement misstatement.","check":"What makes a useful audit-risk answer?","answer":"State the case fact, explain the possible material misstatement and specify an appropriate audit response."},"FM:D1":{"paper":"FM","code":"D1","summary":"Investment appraisal evaluates whether a capital project adds financial value, allowing for the timing and risk of future cash flows.","steps":["Use incremental project cash flows rather than accounting profit; exclude sunk costs.","Discount future cash flows at the specified required return and include relevant working capital and terminal receipts.","Evaluate net present value along with strategic and non-quantified constraints."],"formula":"NPV = Sum of discounted incremental cash flows − Initial outlay.","example":"Invest $10,000 today and collect $6,000 at the end of each of the next two years. At 10%, NPV ≈ $413, suggesting positive value under these assumptions.","trap":"Payback and ARR do not automatically capture the time value of money as NPV does.","check":"If a project has NPV −$700, does it meet the specified discount rate financially?","answer":"No; it falls short of the specified required return under the supplied assumptions."},"SBL:B2":{"paper":"SBL","code":"B2","summary":"Strategic stakeholder analysis examines who can affect a firm's strategy, how expectations differ and how leadership should communicate with each group.","steps":["Identify the stakeholders relevant to the exhibit, their interests and ability to influence the organisation.","Assess trade-offs among short-term returns, ethical duties, governance and sustainability.","Recommend actions that are realistic, justified and tailored to the scenario rather than repeating theory."],"formula":"Prioritisation lens: Stakeholder influence × Stakeholder interest, considered with ethical and legal duties.","example":"A large employer plans a factory closure. Employees, lenders, regulators, customers and the local community require different engagement strategies.","trap":"Do not assume a stakeholder with low power can be ignored where statutory or ethical obligations exist.","check":"Why should an SBL response refer to the exhibit's actual facts?","answer":"Professional marks and decision quality depend on applying analysis to the case rather than listing generic frameworks."},"SBR:C1":{"paper":"SBR","code":"C1","summary":"IFRS 15 revenue recognition uses a five-step model that focuses on the transfer of control of goods or services to customers.","steps":["Identify the contract and the distinct performance obligations promised to the customer.","Determine the transaction price and allocate it across obligations using appropriate stand-alone selling prices.","Recognise revenue when or as each performance obligation is satisfied; reassess variable consideration and contract modifications where required."],"formula":"Five steps: Contract → Performance obligations → Transaction price → Allocation → Revenue recognition.","example":"A company sells equipment with a separately identifiable two-year servicing contract. The transaction price may need allocation between the equipment and servicing obligations, with service revenue recognised over the service period.","trap":"Cash collection, invoice issue and revenue recognition are not necessarily simultaneous.","check":"Why might cash received in advance be shown as a contract liability?","answer":"Because the entity still has a performance obligation to transfer promised goods or services."},"AFM:B1":{"paper":"AFM","code":"B1","summary":"Discounted cash flow (DCF) valuation and appraisal depend on incremental future cash flows and an appropriately justified discount rate.","steps":["Project operating free cash flows after relevant investment in capital expenditure and working capital.","Select the relevant cost of capital and ensure currency, risk and inflation assumptions are consistent.","Calculate present value, examine sensitivity and explain risk to management rather than presenting a point estimate as certain."],"formula":"Present value = Future cash flow ÷ (1 + discount rate)^period.","example":"A $1,210 cash inflow expected in two years discounted at 10% has present value $1,000; this does not include other project cash flows or initial cost.","trap":"Applying a nominal discount rate to real cash flows without conversion can distort NPV.","check":"If discount rates increase but future positive cash flows stay unchanged, what happens to present value?","answer":"Present value generally decreases."},"APM:A3":{"paper":"APM","code":"A3","summary":"Financial performance measures help management evaluate returns and efficiency, but require interpretation alongside organisational objectives.","steps":["Choose financial indicators relevant to strategy, such as ROI, residual income and cash conversion.","Identify the denominator, measurement period and accounting-policy issues behind each ratio.","Consider whether a measure encourages managers to reject value-creating projects or prioritise short-term results."],"formula":"ROI = Controllable profit ÷ Capital employed × 100%.","example":"A division reports profit $300,000 on average capital employed $2,000,000: ROI = 15%. Whether performance is adequate depends on target return and strategy.","trap":"A rising ratio does not prove long-run value creation if important non-financial drivers are deteriorating.","check":"A division earns $100,000 profit on $1m capital and its capital charge is 8%. Residual income?","answer":"$20,000 = $100,000 − $80,000 capital charge."},"ATX:A6":{"paper":"ATX","code":"A6","summary":"Stamp duty in the Malaysian ATX syllabus requires careful identification of dutiable instruments, exemptions, valuation and procedures for the examinable period.","steps":["Determine the type of instrument and whether Malaysian stamp duty applies.","Identify its chargeable value, applicable rate structure and any relief or exemption under the prescribed tax-year rules.","Explain the timing, documentation and compliance consequences using current examinable legal provisions."],"formula":"Duty assessment = Dutiable base × Applicable duty structure (where an ad valorem rate applies).","example":"When a company transfers a chargeable property, first establish instrument type, transaction value and relevant exemptions before computing duty under the examinable table.","trap":"Do not copy outdated fixed rates, brackets or thresholds from online examples into a 2026–27 exam answer.","check":"Why should an ATX candidate avoid answering without the instrument's details?","answer":"Stamp duty treatment can depend on the precise nature of the instrument and the transaction."},"AAA:D1":{"paper":"AAA","code":"D1","summary":"Advanced audit planning examines financial statement risks, materiality and the auditor's evidence strategy, applying professional scepticism to the case.","steps":["Assess business developments and explain the precise risk of material misstatement by account and assertion.","Set and reassess materiality using justified benchmarks and professional judgment.","Plan proportionate responses, especially for complex accounting estimates, related-party dealings and group reporting."],"formula":"Overall materiality may be derived from a justified percentage of an appropriate benchmark; no single rate is universally correct.","example":"A highly judgmental acquisition valuation increases the risk of material misstatement. Auditors need to examine models, assumptions and source evidence, with specialist input when appropriate.","trap":"A management estimate being difficult does not automatically prove fraud; distinguish uncertainty, bias and evidence.","check":"What is the difference between audit risk and audit response?","answer":"Audit risk describes what could be materially wrong; an audit response sets out how the auditor will obtain evidence to address it."}};})(typeof window!=='undefined'?window:globalThis);
